function Get-HrsConfiguredOdds {
    $odds = [ordered]@{}
    foreach ($biome in $biomes) { $odds[$biome] = 0.0 }
    if (-not $randomRadio.Checked) { return $odds }
    if ($selectionCombo.SelectedIndex -eq 0) {
        foreach ($biome in $biomes) { $odds[$biome] = 100.0 / $biomes.Count }
    }
    elseif ($selectionCombo.SelectedIndex -eq 1) {
        $odds[[string]$chosenCombo.SelectedItem] = 100.0
    }
    else {
        $total = 0.0
        foreach ($biome in $biomes) { $total += [double]$weights[$biome] }
        if ($total -gt 0) {
            foreach ($biome in $biomes) { $odds[$biome] = 100.0 * [double]$weights[$biome] / $total }
        }
    }
    return $odds
}

function Update-HrsBiomePreview {
    $script:managerNotice = ''
    $isRandom = $randomRadio.Checked
    $biomeGroup.Enabled = $isRandom
    $biomeProtectCheck.Enabled = $isRandom
    $biomeGroup.Visible = $isRandom
    $biomeProtectCheck.Visible = $isRandom
    $biomeNote.Visible = $isRandom
    if ($null -ne $script:modeNote) { $script:modeNote.Visible = !$isRandom }
    $chosenCombo.Visible = $isRandom -and $selectionCombo.SelectedIndex -eq 1
    $editWeights.Visible = $isRandom -and $selectionCombo.SelectedIndex -eq 2
    $selectionNote.Visible = $isRandom -and $selectionCombo.SelectedIndex -eq 2
    $total = 0
    foreach ($biome in $biomes) { $total += [int]$weights[$biome] }
    if (-not $isRandom) { $selectionNote.Text = 'Keep the usual starting location.' }
    elseif ($selectionCombo.SelectedIndex -eq 0) { $selectionNote.Text = '' }
    elseif ($selectionCombo.SelectedIndex -eq 1) { $selectionNote.Text = '' }
    else { $selectionNote.Text = $script:hrsDesignRecipe.copy.manager.weightedHelp }
    if ($null -ne $script:weightSummary) {
        $script:weightSummary.Visible = $isRandom -and $selectionCombo.SelectedIndex -eq 2
        $odds = Get-HrsConfiguredOdds
        $script:weightSummary.Text = (@($biomes | ForEach-Object { '{0} {1:0.#}%' -f $_,$odds[$_] }) -join '  /  ')
    }
    Update-HrsStatus
    if (!$SmokeTest) { Fit-HrsManagerWindow }
}

function Show-WeightEditor {
    param([string] $CapturePath = '', [ValidateSet('None','Cancel','Save')] [string] $TestAction='None')
    $dialog = New-Object Windows.Forms.Form
    $dialog.Text = 'Bit Wrecked - Biome weights'
    $dialog.Icon = $form.Icon; $dialog.Font = $form.Font
    $dialog.StartPosition = 'CenterParent'; $dialog.FormBorderStyle = 'FixedDialog'
    $dialog.MinimizeBox = $false; $dialog.MaximizeBox = $false
    $dialog.AutoScaleMode = 'Font'; $dialog.AutoScroll = $true
    $dialog.ClientSize = New-Object Drawing.Size(480,390)
    $dialogFonts = New-Object 'Collections.Generic.List[IDisposable]'
    $dialog.Add_Disposed({foreach ($font in $dialogFonts) { $font.Dispose() }})
    $frame = New-Object Windows.Forms.TableLayoutPanel
    $frame.AutoSize = $true; $frame.Dock = 'Top'; $frame.ColumnCount = 1
    [void]$frame.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,100)))
    $frame.Padding = New-Object Windows.Forms.Padding(12)
    $dialog.Controls.Add($frame)
    $surface = New-Object BitWrecked.NativeGraphics.V1.SurfacePanel
    $surface.Dock = 'Top'; $surface.AutoSize = $false
    $surface.Padding = New-Object Windows.Forms.Padding(0)
    $surface.FillColor = [Drawing.ColorTranslator]::FromHtml($script:hrsDesignRecipe.palette.surface)
    $surface.BorderColor = [Drawing.ColorTranslator]::FromHtml($script:hrsDesignRecipe.palette.border)
    $surface.CornerRadius = [float]$script:hrsDesignRecipe.geometry.cornerRadius
    $surface.Margin = New-Object Windows.Forms.Padding(0)
    $frame.Controls.Add($surface,0,0)
    $column = New-Object Windows.Forms.TableLayoutPanel
    $column.AutoSize = $true; $column.Dock = 'Top'; $column.ColumnCount = 1
    [void]$column.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,100)))
    $column.Padding = New-Object Windows.Forms.Padding(24)
    $surface.Controls.Add($column)
    $heading = New-Object Windows.Forms.Label
    $heading.Text = 'Biome weights'; $heading.AutoSize = $true
    $heading.Font = New-HrsFont 17 $dialogFonts
    $help = New-Object Windows.Forms.Label
    $help.Text = '0 excludes a biome. Use at least one positive weight. Shares adjust to the biomes in your world.'
    $help.AutoSize = $true; $help.MaximumSize = New-Object Drawing.Size(396,0); $help.Tag = 'Muted'
    $grid = New-Object Windows.Forms.TableLayoutPanel
    $grid.AutoSize = $true; $grid.ColumnCount = 3
    [void]$grid.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,42)))
    [void]$grid.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,24)))
    [void]$grid.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,34)))
    $editControls = [ordered]@{}; $chanceLabels = [ordered]@{}
    for ($i=0; $i -lt $biomes.Count; $i++) {
        $biome = $biomes[$i]
        $label = New-Object Windows.Forms.Label
        $label.Text = $biome; $label.AutoSize = $true; $label.Anchor = 'Left'
        $label.Margin = New-Object Windows.Forms.Padding(0,6,8,10)
        $numeric = New-Object Windows.Forms.NumericUpDown
        $numeric.Minimum = 0; $numeric.Maximum = 100; $numeric.Value = [int]$weights[$biome]
        $numeric.Width = 78; $numeric.Anchor = 'Left'; $numeric.TabIndex = $i
        $numeric.Margin = New-Object Windows.Forms.Padding(0,3,8,8)
        $numeric.AccessibleName = "$biome weight"
        $chance = New-Object Windows.Forms.Label
        $chance.AutoSize = $true; $chance.Anchor = 'Left'; $chance.Tag = 'Muted'
        $chance.Margin = New-Object Windows.Forms.Padding(0,6,0,10)
        $grid.Controls.Add($label,0,$i); $grid.Controls.Add($numeric,1,$i); $grid.Controls.Add($chance,2,$i)
        $editControls[$biome] = $numeric; $chanceLabels[$biome] = $chance
    }
    $actions = New-Object Windows.Forms.FlowLayoutPanel
    $actions.AutoSize = $true; $actions.WrapContents = $true
    $save = New-Object BitWrecked.NativeGraphics.V1.OutlineButton
    $save.Text = 'Use Weights'; $save.Size = New-Object Drawing.Size(154,[int]$script:hrsDesignRecipe.geometry.buttonHeight)
    $save.Margin = New-Object Windows.Forms.Padding(0,0,12,0)
    Set-HrsButtonStyle $save Secondary
    $cancel = New-Object BitWrecked.NativeGraphics.V1.OutlineButton
    $cancel.Text = 'Cancel'; $cancel.Size = New-Object Drawing.Size(130,[int]$script:hrsDesignRecipe.geometry.buttonHeight)
    $cancel.Margin = New-Object Windows.Forms.Padding(0)
    Set-HrsButtonStyle $cancel Secondary
    $cancel.DialogResult = [Windows.Forms.DialogResult]::Cancel
    $actions.Controls.AddRange([Windows.Forms.Control[]]@($save,$cancel))
    $dialog.AcceptButton = $save; $dialog.CancelButton = $cancel
    $row=0
    foreach ($control in @($heading,$help,$grid,$actions)) {
        $control.Dock = 'Top'; $control.Margin = New-Object Windows.Forms.Padding(0,0,0,12)
        $control.TabIndex = $row; $column.Controls.Add($control,0,$row); $row++
    }
    $actions.Margin = New-Object Windows.Forms.Padding(0)
    $updateEditor = {
        $total=0.0
        foreach ($biome in $biomes) { $total += [double]$editControls[$biome].Value }
        foreach ($biome in $biomes) {
            $chance = if ($total -gt 0) { 100.0*[double]$editControls[$biome].Value/$total } else { 0.0 }
            $chanceLabels[$biome].Text = ('{0:N1}% share' -f $chance)
        }
        $save.Enabled = $total -gt 0
    }
    foreach ($biome in $biomes) { $editControls[$biome].Add_ValueChanged($updateEditor) }
    & $updateEditor
    $save.Add_Click({
        foreach ($biome in $biomes) { $weights[$biome] = [int]$editControls[$biome].Value }
        $dialog.DialogResult = [Windows.Forms.DialogResult]::OK
        $dialog.Close()
    })
    $dialog.Add_SystemColorsChanged({param($sender,$eventArgs); Update-HrsPresentationColors -Owner $sender})
    Update-HrsPresentationColors -Owner $dialog
    $dialog.Add_Shown({
        $column.PerformLayout()
        $surface.Height = $column.Height
        $frame.PerformLayout()
        $dialog.PerformLayout()
        $workArea = [Windows.Forms.Screen]::FromControl($form).WorkingArea
        $chrome = $dialog.Height-$dialog.ClientSize.Height
        $dialog.ClientSize = New-Object Drawing.Size($dialog.ClientSize.Width,([Math]::Min($frame.PreferredSize.Height+4,$workArea.Height-$chrome-24)))
    })
    try {
        if ($SmokeTest -and $TestAction -ne 'None') {
            $dialog.Show($form); [Windows.Forms.Application]::DoEvents()
            foreach ($biome in $biomes) { $editControls[$biome].Value=0 }
            if ($save.Enabled) { throw 'EDITOR_ALL_ZERO_NOT_BLOCKED' }
            $editControls['Wasteland'].Value=100
            if (!$save.Enabled) { throw 'EDITOR_POSITIVE_BLOCKED' }
            if ($TestAction -eq 'Save') { $save.PerformClick() } else { $cancel.PerformClick() }
            Update-HrsBiomePreview
            return
        }
        if ($SmokeTest -and $UiScale -ne 1) { $dialog.Scale((New-Object Drawing.SizeF($UiScale,$UiScale))) }
        if (![string]::IsNullOrWhiteSpace($CapturePath)) {
            $dialog.Show($form); [Windows.Forms.Application]::DoEvents()
            $bitmap = New-Object Drawing.Bitmap($dialog.Width,$dialog.Height)
            try { $dialog.DrawToBitmap($bitmap,(New-Object Drawing.Rectangle(0,0,$dialog.Width,$dialog.Height))); $bitmap.Save($CapturePath,[Drawing.Imaging.ImageFormat]::Png) }
            finally { $bitmap.Dispose() }
            $dialog.Close()
            return
        }
        [void]$dialog.ShowDialog($form)
        Update-HrsBiomePreview
    } finally { $dialog.Dispose() }
}

