$biomeIds=@(3,9,5,1,8)
function Get-HrsFormSelection {
    if (!$randomRadio.Checked -or $selectionCombo.SelectedIndex -eq 0) {return @{Selection='Any';ChosenBiome=0;Weights=@(0,0,0,0,0)}}
    if ($selectionCombo.SelectedIndex -eq 1) {return @{Selection='Chosen';ChosenBiome=$biomeIds[$chosenCombo.SelectedIndex];Weights=@(0,0,0,0,0)}}
    return @{Selection='Weighted';ChosenBiome=0;Weights=@($biomes | ForEach-Object { [int]$weights[$_] })}
}
function Get-HrsFormDescription {
    if (!$randomRadio.Checked) {return 'Standard start'}
    if ($selectionCombo.SelectedIndex -eq 0) {return 'Biome: Any eligible (equal chance)'}
    if ($selectionCombo.SelectedIndex -eq 1) {return "Biome: $($chosenCombo.SelectedItem)"}
    return 'Biome weights: '+(($biomes | ForEach-Object {"$_ $($weights[$_])"}) -join ', ')
}
function Set-HrsFormFromPolicy {
    param([Parameter(Mandatory=$true)][psobject]$Policy)
    $gameNameBox.Text = $Policy.gameName
    $randomRadio.Checked = $Policy.mode -ne 'Standard'
    $standardRadio.Checked = !$randomRadio.Checked
    $biomeProtectCheck.Checked = $Policy.mode -eq 'RandomSafe'
    $savedArgs = Get-HrsSelectionArguments $Policy
    $selectionCombo.SelectedIndex = @('Any','Chosen','Weighted').IndexOf($savedArgs.Selection)
    if ($savedArgs.Selection -eq 'Chosen') {
        $chosenCombo.SelectedIndex = @($biomeIds).IndexOf([int]$savedArgs.ChosenBiome)
    }
    if ($savedArgs.Selection -eq 'Weighted') {
        for($i=0;$i -lt 5;$i++){ $weights[$biomes[$i]]=$savedArgs.Weights[$i] }
    }
    Update-HrsBiomePreview
}
function Set-HrsButtonStyle {
    param([Windows.Forms.Button] $Button, [ValidateSet('Primary','Secondary','Quiet')] [string] $Role)
    $Button.UseVisualStyleBackColor = $false
    $Button.UseMnemonic = $false
    $Button.FillColor = [Drawing.ColorTranslator]::FromHtml($script:hrsDesignRecipe.palette.buttonFill)
    $Button.BorderColor = [Drawing.Color]::FromArgb(133,135,127)
    $Button.AccentColor = $script:hrsAccentColor
    $Button.HoverColor = [Drawing.Color]::FromArgb(241,241,237)
    $Button.CornerRadius = [float]$script:hrsDesignRecipe.geometry.cornerRadius
    $Button.ForeColor = if ($Role -eq 'Quiet') { $script:hrsMutedColor } else { $form.ForeColor }
    $Button.Tag = $Role
    $Button.Cursor = if ($Button.Enabled) { [Windows.Forms.Cursors]::Hand } else { [Windows.Forms.Cursors]::Default }
    $Button.Add_EnabledChanged({param($sender,$eventArgs); $sender.Cursor = if ($sender.Enabled) { [Windows.Forms.Cursors]::Hand } else { [Windows.Forms.Cursors]::Default }})
}

function Update-HrsPresentationColors {
    param([switch]$ForceHighContrast,[Windows.Forms.Form]$Owner=$form)
    $highContrast = $ForceHighContrast -or [Windows.Forms.SystemInformation]::HighContrast
    $palette = $script:hrsDesignRecipe.palette
    $Owner.BackColor = if ($highContrast) { [Drawing.SystemColors]::Window } else { [Drawing.ColorTranslator]::FromHtml($palette.background) }
    $Owner.ForeColor = if ($highContrast) { [Drawing.SystemColors]::ControlText } else { [Drawing.ColorTranslator]::FromHtml($palette.text) }
    $queue = New-Object 'Collections.Generic.Queue[Windows.Forms.Control]'
    $queue.Enqueue($Owner)
    while ($queue.Count) {
        $control = $queue.Dequeue()
        if ($control -is [BitWrecked.NativeGraphics.V1.SurfacePanel] -or $control -is [BitWrecked.NativeGraphics.V1.OutlineButton] -or $control -is [BitWrecked.NativeGraphics.V1.StatusBadge]) {
            $control.PreviewHighContrast = [bool]$ForceHighContrast
        }
        if ($control -is [Windows.Forms.Label]) {
            $control.BackColor = [Drawing.Color]::Transparent
            $control.ForeColor = if ($highContrast) { [Drawing.SystemColors]::ControlText } elseif ($control.Tag -eq 'Accent') { $script:hrsAccentColor } elseif ($control.Tag -eq 'Muted') { $script:hrsMutedColor } else { $Owner.ForeColor }
            if ($control -is [Windows.Forms.LinkLabel]) {
                $control.LinkColor = if ($highContrast) { [Drawing.SystemColors]::HotTrack } else { $script:hrsMutedColor }
                $control.ActiveLinkColor = if ($highContrast) { [Drawing.SystemColors]::Highlight } else { $script:hrsAccentColor }
                $control.VisitedLinkColor = $control.LinkColor
            }
        } elseif ($control -is [Windows.Forms.TextBox] -or $control -is [Windows.Forms.ComboBox] -or $control -is [Windows.Forms.NumericUpDown]) {
            $control.BackColor = if ($highContrast) { [Drawing.SystemColors]::Window } else { [Drawing.ColorTranslator]::FromHtml($palette.surface) }
            $control.ForeColor = if ($highContrast) { [Drawing.SystemColors]::WindowText } else { $Owner.ForeColor }
        } elseif ($control -is [BitWrecked.NativeGraphics.V1.OutlineButton]) {
            $control.ForeColor = if ($control.Tag -eq 'Quiet') { $script:hrsMutedColor } else { $Owner.ForeColor }
        } elseif ($control -is [Windows.Forms.TableLayoutPanel] -or $control -is [Windows.Forms.FlowLayoutPanel]) {
            $control.BackColor = if ($highContrast) { [Drawing.SystemColors]::Control } else { [Drawing.Color]::Transparent }
        } elseif ($control -is [Windows.Forms.CheckBox] -or $control -is [Windows.Forms.RadioButton]) {
            $control.BackColor = [Drawing.Color]::Transparent
            $control.ForeColor = $Owner.ForeColor
        }
        foreach ($child in $control.Controls) { $queue.Enqueue($child) }
    }
    $Owner.Invalidate($true)
}

function Update-HrsTextWidths {
    if ($null -eq $script:managerLayout -or $script:managerLayoutUpdating) { return }
    $script:managerLayoutUpdating = $true
    try {
    $available = [Math]::Max(180, $script:managerLayout.ClientSize.Width - $script:managerLayout.Padding.Horizontal - 6)
    foreach ($label in @($script:managerIntro,$gameNameHelp,$script:modeNote,$biomeNote,$resultStatus,$script:resultSummary,$details,$status,$script:nextAction)) {
        $label.MaximumSize = New-Object Drawing.Size($available,0)
    }
    $releaseWidth = $version.GetPreferredSize([Drawing.Size]::Empty).Width + $version.Margin.Horizontal
    $titleWidth = [Math]::Max(80,$available-$script:managerBrand.Width-$script:managerBrand.Margin.Horizontal-$releaseWidth)
    $title.MaximumSize = New-Object Drawing.Size($titleWidth,0)
    $biomeGroup.PerformLayout()
    $choiceWidth = [Math]::Max(140,$script:biomeChoices.ClientSize.Width-$script:biomeChoices.Padding.Horizontal-6)
    foreach ($label in @($selectionNote,$script:weightSummary)) {
        $label.MaximumSize = New-Object Drawing.Size($choiceWidth,0)
    }
    $script:biomeChoices.PerformLayout()
    $biomeGroup.Height = $script:biomeChoices.Height
    $script:managerLayout.PerformLayout()
    $script:managerSurface.Height = $script:managerLayout.Height
    $script:managerFrame.PerformLayout()
    } finally { $script:managerLayoutUpdating = $false }
}

function Fit-HrsManagerWindow {
    if (!$form.Visible -or $form.WindowState -ne [Windows.Forms.FormWindowState]::Normal -or $script:managerUserResized -or $script:managerFitting) { return }
    $script:managerFitting = $true
    try {
        Update-HrsTextWidths
        $form.PerformLayout()
        $workArea = [Windows.Forms.Screen]::FromControl($form).WorkingArea
        $chrome = $form.Height - $form.ClientSize.Height
        $desired = $script:managerFrame.PreferredSize.Height + $form.AutoScrollMargin.Height + 4
        $height = [Math]::Max(320,[Math]::Min($desired,($workArea.Height-$chrome-24)))
        $form.ClientSize = New-Object Drawing.Size($form.ClientSize.Width,$height)
    } finally { $script:managerFitting = $false }
}

function Update-HrsStatusPresentation {
    if ($null -eq $script:managerStatePanel) { return }
    $pendingChanges = $status.Text -ceq 'Changes not applied.'
    $appliedChanges = $status.Text -ceq 'Settings ready.'
    $showApplyState = $pendingChanges -or $appliedChanges
    if ($null -ne $script:applyStatus) {
        if ($showApplyState) {
            $script:applyStatus.Text = if ($pendingChanges) { 'Changes not applied.' } else { 'Changes applied.' }
            $script:applyStatus.AccessibleName = $script:applyStatus.Text.TrimEnd('.')
            $script:applyStatus.FillColor = [Drawing.ColorTranslator]::FromHtml($(if ($pendingChanges) { '#FFF6E6' } else { '#EDF6EF' }))
            $script:applyStatus.BorderColor = [Drawing.ColorTranslator]::FromHtml($(if ($pendingChanges) { '#E6C994' } else { '#B7D3BE' }))
            $script:applyStatus.ForeColor = [Drawing.ColorTranslator]::FromHtml($(if ($pendingChanges) { '#805A21' } else { '#316D41' }))
            $script:applyStatus.AccentColor = [Drawing.ColorTranslator]::FromHtml($(if ($pendingChanges) { '#AE7119' } else { '#3F7D50' }))
        }
        $script:applyStatus.Visible = $showApplyState
    }
    $showStatus = ![string]::IsNullOrWhiteSpace($status.Text) -and !$showApplyState
    $showNext = ![string]::IsNullOrWhiteSpace($script:nextAction.Text) -and $script:nextAction.Text -cne 'Apply settings to use this start.'
    $status.Visible = $showStatus
    $script:nextAction.Visible = $showNext
    $script:managerStatePanel.Visible = $showStatus -or $showNext
}

